export function serveQuarantineFiles () {
  return ({ params, query }: Request, res: Response, next: NextFunction) => {
    const file = params.file

    // Sanitize user input to prevent path traversal
    const sanitizedPath = file.replace(/^(\.\.(\/|\\|$))+/, '')

    // Check for NULL byte
    if (sanitizedPath.indexOf('\0') !== -1) {
      res.status(403)
      next(new Error('Invalid file name!'))
      return
    }

    // Validate the final path
    const resolvedPath = path.resolve('ftp/quarantine/', sanitizedPath)
    if (!resolvedPath.startsWith(path.resolve('ftp/quarantine/'))) {
      res.status(403)
      next(new Error('File path is not within the allowed directory!'))
      return
    }

    if (!file.includes('/')) {
      res.sendFile(resolvedPath)
    } else {
      res.status(403)
      next(new Error('File names cannot contain forward slashes!'))
    }
  }
}

